<script setup lang="ts">
import { ref, watch, onBeforeUnmount } from 'vue'
import { ApiError, type LoginResponse } from '../client'
import { shopApi, type Purchase } from '../shop-client'
import { accountApi, type Address } from '../account-client'
import { formatMinorUnits } from '../money'
import UserAvatar from './UserAvatar.vue'
import ProductArt from './ProductArt.vue'
import StoreMark from './StoreMark.vue'
const props = defineProps<{ account: LoginResponse }>()
const emit = defineEmits<{ navigate: [hash: string]; expired: [] }>()
const orders = ref<Purchase[]>([]), address = ref<Address | null>(null), loading = ref(false), orderError = ref(''), addressError = ref('')
let generation = 0
const stages = [{ name: '待付款', status: 'WAITING_PAYMENT' }, { name: '待发货', status: 'AWAITING_SHIPMENT' }, { name: '待收货', status: 'AWAITING_RECEIPT' }, { name: '已完成', status: 'COMPLETED' }, { name: '售后', status: 'AFTER_SALES' }]
const labels: Record<string,string> = { WAITING_PAYMENT:'待付款', PAYMENT_PENDING:'付款确认中', PAID:'已付款', CANCELLED:'已取消', EXPIRED:'已关闭', AWAITING_SHIPMENT:'待发货', AWAITING_RECEIPT:'待收货', COMPLETED:'已完成', AFTER_SALES:'售后处理中', LOGISTICS_UNKNOWN:'物流待确认' }
const links = [{ title: '个人资料', hash: '#/shop/profile' }, { title: '账号安全', hash: '#/shop/security' }, { title: '消息', hash: '#/shop/messages' }, { title: '售后咨询', hash: '#/shop/support' }]
function unavailable(error: unknown) { if (error instanceof ApiError && error.status === 401) emit('expired') }
async function load() {
  const g = ++generation; loading.value = true; orderError.value = ''; addressError.value = ''; orders.value = []; address.value = null
  const [purchases, addresses] = await Promise.allSettled([shopApi.purchases(props.account.access_token), accountApi.addresses(props.account.access_token)])
  if (g !== generation) return
  if (purchases.status === 'fulfilled') orders.value = purchases.value.items.slice(0,3)
  else { orderError.value = '订单暂时无法读取'; unavailable(purchases.reason) }
  if (addresses.status === 'fulfilled') address.value = addresses.value.items.find(a => a.is_default) ?? addresses.value.items[0] ?? null
  else { addressError.value = '地址暂时无法读取'; unavailable(addresses.reason) }
  loading.value = false
}
watch(() => props.account.access_token, load, { immediate: true }); onBeforeUnmount(() => { generation++ })
</script>
<template><main class="personal-center"><header class="personal-header"><UserAvatar :token="account.access_token" source="/api/v1/account/avatar" :name="account.display_name" :size="64" /><div><h1>{{ account.display_name || '我的账户' }}</h1><a href="#/shop/profile" @click.prevent="emit('navigate','#/shop/profile')">编辑资料</a></div></header>
<section class="personal-orders" aria-label="购物阶段"><div class="personal-heading"><h2>我的订单</h2><a href="#/shop/orders" @click.prevent="emit('navigate','#/shop/orders')">全部订单</a></div><div class="personal-stages"><button v-for="stage in stages" :key="stage.status" @click="emit('navigate',stage.status === 'AFTER_SALES' ? '#/customer/applications' : `#/shop/orders?status=${stage.status}`)">{{ stage.name }}</button></div></section>
<div class="personal-grid"><section class="personal-recent"><div class="personal-heading"><h2>最近订单</h2><button :disabled="loading" @click="load">刷新</button></div><p v-if="loading">正在读取…</p><p v-else-if="orderError" role="alert">{{ orderError }}</p><div v-else-if="!orders.length" class="personal-empty"><p>还没有订单</p><a href="#/shop" @click.prevent="emit('navigate','#/shop')">去挑选喜欢的商品</a></div><a v-for="order in orders" :key="order.purchase_id" class="personal-order" :href="`#/shop/orders/${encodeURIComponent(order.purchase_id)}`" @click.prevent="emit('navigate',`#/shop/orders/${encodeURIComponent(order.purchase_id)}`)"><ProductArt v-if="order.lines[0]?.asset_key" :asset="order.lines[0].asset_key" :name="order.lines[0].product_name || '商品'" :variant="order.lines[0].variant || undefined" /><div><span class="personal-order-store"><StoreMark :id="order.store_id" :size="15" />{{ order.store_name }}</span><h3>{{ order.lines[0]?.product_name || '订单商品' }}<span v-if="order.lines.length > 1"> 等{{ order.lines.length }}款</span></h3><span>{{ labels[order.shopping_stage || order.status] || '查看订单' }}</span></div><strong>¥{{ formatMinorUnits(order.total_amount).replace(' CNY','') }}</strong></a></section>
<aside><section class="personal-address"><div class="personal-heading"><h2>{{ address?.is_default ? '默认收货地址' : '收货地址' }}</h2><a href="#/shop/addresses" @click.prevent="emit('navigate','#/shop/addresses')">管理</a></div><p v-if="addressError" role="alert">{{ addressError }}</p><template v-else-if="address"><strong>{{ address.recipient }}</strong><span>{{ address.phone }}</span><p>{{ address.province }} {{ address.city }} {{ address.district }} {{ address.detail }}</p></template><a v-else-if="!loading" href="#/shop/addresses" @click.prevent="emit('navigate','#/shop/addresses')">添加收货地址</a></section><nav aria-label="账户管理"><a v-for="link in links" :key="link.hash" :href="link.hash" @click.prevent="emit('navigate',link.hash)">{{ link.title }}</a></nav></aside></div>
</main></template>
<style scoped>
.personal-center{max-width:1120px;margin:auto;padding:36px 28px;color:#293d34}.personal-header{display:flex;gap:18px;align-items:center;margin-bottom:28px}.personal-center h1{font-size:24px;margin:0 0 8px}.personal-center h2{font-size:17px;margin:0}.personal-center a{text-decoration:none;color:inherit}.personal-center button{font:inherit;cursor:pointer;background:transparent;border:0;color:#205e50}.personal-header a,.personal-heading a,.personal-heading button{font-size:13px;color:#205e50}.personal-orders,.personal-recent,.personal-address,.personal-center nav{background:white;border:1px solid #e0e5dc;border-radius:12px;padding:22px}.personal-orders{margin-bottom:24px}.personal-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:20px}.personal-stages{display:flex;justify-content:space-around;gap:12px}.personal-stages button{padding:12px 6px!important;background:transparent!important;font-size:14px!important}.personal-stages button:hover{color:#176b5c!important}.personal-grid{display:grid;grid-template-columns:minmax(0,1.75fr) minmax(260px,1fr);gap:24px}.personal-order{display:flex;align-items:center;gap:16px;padding:18px 0;border-top:1px solid #e9ece5}.personal-order>img,.personal-order>svg{width:76px;height:76px;flex-shrink:0;border-radius:8px;object-fit:cover}.personal-order>div{flex:1;min-width:0}.personal-order h3{font-size:15px;margin:7px 0!important;overflow-wrap:anywhere}.personal-order-store{display:flex;align-items:center;gap:6px;font-size:12px;color:#758175}.personal-order>div>span:last-child{font-size:13px;color:#68766b}.personal-order>strong{font-size:14px;white-space:nowrap}.personal-address>span{display:block;color:#68766b;font-size:14px;margin-top:8px}.personal-address p{font-size:14px;line-height:1.8;margin:12px 0 0;overflow-wrap:anywhere}.personal-center nav{display:grid;grid-template-columns:1fr 1fr;gap:0;margin-top:20px;padding:10px}.personal-center nav a{padding:16px 12px;font-size:14px}.personal-empty{padding:36px 0;text-align:center;color:#758175;font-size:14px}.personal-empty a,.personal-address>a{color:#176b5c;font-size:14px}@media(max-width:700px){.personal-center{padding:24px 16px}.personal-grid{grid-template-columns:1fr}.personal-stages{flex-wrap:wrap}.personal-order>strong{font-size:13px}.personal-orders,.personal-recent,.personal-address{padding:18px}.personal-order{gap:10px}.personal-order>img,.personal-order>svg{width:60px;height:60px}}
</style>
